with recursive var_2 (mq_id,mq_parentId,mq_name,mq_level) as (select fne1_0.id,fne1_0.parent_id,fne1_0.name,0 from folder_nodes fne1_0 where fne1_0.id in (?) union all select fne2_0.id,fne2_0.parent_id,fne2_0.name,(var_21_0.mq_level+cast(? as integer)) from var_2 var_21_0,folder_nodes fne2_0 where fne2_0.parent_id=var_21_0.mq_id and var_21_0.mq_level<?) cycle mq_id set mqCycleMark to true default false using path select fne3_0.id,var_1_11_0.mq_level,(select min(var_22_0.mq_id) from var_2 var_22_0 where var_22_0.mq_level>?),(select min(var_23_0.mq_id) from var_2 var_23_0 where var_23_0.mqCycleMark),(select var_24_0.mq_id from var_2 var_24_0 group by 1 having count(1)>? order by 1 fetch first ? rows only) from folder_nodes fne3_0 left join var_2 var_1_11_0 on var_1_11_0.mq_id=fne3_0.id and var_1_11_0.mq_level<=? and not(var_1_11_0.mqCycleMark) where fne3_0.id<=? order by 1
